const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>`\u20B9${Number(v||0).toLocaleString('en-IN')}`;
const date=n=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const S={token:localStorage.getItem('gorent_token'),user:null,view:'home',cars:[],bookings:[],mine:[],car:null,ownerQuery:'',ownerStatus:'all',ownerPanel:'overview',f:{q:'',city:'',fuel:'',transmission:'',category:'',max_price:'',sort:'rating',from:date(1),to:date(3),bookingType:'daily',hourFrom:'',hourTo:''}};
let timer;function toast(s,bad=false){const e=$('#toast');e.textContent=s;e.className=bad?'on bad':'on';clearTimeout(timer);timer=setTimeout(()=>e.className='',3500)}
function err(d){return typeof d==='string'?d:d?.detail||Object.entries(d||{}).map(([k,v])=>`${k}: ${Array.isArray(v)?v.join(', '):v}`).join(' · ')||'Request failed'}
async function api(p,{method='GET',body,auth=true}={}){const headers={};if(auth&&S.token)headers.Authorization=`Token ${S.token}`;if(body&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body)}const base=String(window.GORENT_API_BASE||'').replace(/\/$/,'');const r=await fetch(`${base}/api/${p}`,{method,headers,body}),d=await r.json().catch(()=>({detail:'Invalid server response'}));if(!r.ok){if(r.status===401&&auth)signout(false);throw Error(err(d))}return d}
function signout(show=true){S.token=null;S.user=null;localStorage.removeItem('gorent_token');S.view='home';S.navTarget='home';S.ownerQuery='';S.ownerStatus='all';S.mine=[];S.bookings=[];if(show){render();toast('Signed out')}}
async function refresh(){if(S.user?.role==='owner'){[S.mine,S.bookings]=await Promise.all([api('vehicles/mine'),api('bookings')]);S.cars=[]}else{const p=new URLSearchParams();for(const k of ['q','city','fuel','transmission','category','max_price','sort'])if(S.f[k]&&S.f[k]!=='rating')p.set(k,S.f[k]);if(S.f.to>S.f.from){p.set('from',S.f.from);p.set('to',S.f.to)}S.cars=await api(`vehicles?${p}`,{auth:false});if(S.user)S.bookings=await api('bookings')}render()}
const title=s=>String(s||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()),chip=s=>`<span class="chip ${['published','verified','active','completed'].includes(s)?'g':['rejected','cancelled'].includes(s)?'r':'y'}">${esc(title(s))}</span>`,opts=(a,v)=>a.map(x=>`<option ${x===v?'selected':''}>${esc(x)}</option>`).join('');
function nav(){const u=S.user,L=u?.role==='owner'?[['home','Home'],['explore','Explore'],['search','Search'],['history','History'],['owner','Dashboard']]:[['home','Home'],['explore','Explore'],['search','Search'],['history','History']],current=S.view==='home'&&u?.role!=='owner'?(S.navTarget||'home'):S.view;if(u?.role==='customer')L.push(['trips','My trips']);$('#nav').innerHTML=L.map(([v,n])=>`<button type="button" data-nav="${v}" class="${current===v?'on':''}" ${current===v?'aria-current="page"':''}>${n}</button>`).join('');$('#account').innerHTML=u?`<span class="mut sm account-name">${esc(u.first_name||u.email)}</span><button class="btn ghost s" data-a="logout">Sign out</button>`:`<button class="btn ghost s" data-a="go" data-id="login">Sign in</button><button class="btn s" data-a="go" data-id="register">Join</button>`}
function render(){const ownerMode=S.user?.role==='owner';document.body.classList.toggle('landing-page',S.view==='home');document.body.classList.toggle('owner-page',ownerMode);document.body.classList.toggle('dashboard-page',ownerMode&&S.view==='owner');nav();const pages=ownerMode?{home:ownerHome,explore:ownerExplore,search:ownerSearch,history:ownerHistory,owner,trips,car,login,register}:{home,car,owner,trips,login,register,history:historyView};$('#app').innerHTML=(pages[S.view]||home)();syncHeadline();enhance()}
const renterHeadlines=[
  'Gift Her an Unforgettable Drive: Rent Her Dream Car for a Few Hours.',
  'Make Her Day Special: Surprise Her with Her Dream Ride Today.',
  'Turn Her Dream Ride into Reality—Available by the Hour.',
  'Surprise Her: Hourly Dream Car Rentals',
  'The Ultimate Date Night Ride',
  'Rent Her Dream Ride by the Hour'
];
const ownerHeadlines=[
  'Turn your idle car into a money-making machine.',
  'Let your car earn for you while you rest.',
  'List your car today and start receiving rental requests.',
  'Your parked car is lost cash. Rent it out now.',
  'Smart car owners don\'t just drive—they earn.',
  'Review renter IDs, approve requests, and set pickup on your terms.',
  'Maximize your car’s value with zero hassle.',
  'Offset your car\'s EMI by sharing your ride.',
  'Your car, your rules, your extra income.',
  'Join our elite host community and grow your wealth.'
];
let headlineIndex=0,headlineRole=null,headlineTimer;
const activeHeadlines=()=>S.user?.role==='owner'?ownerHeadlines:renterHeadlines;
function scheduleHeadline(){clearTimeout(headlineTimer);headlineTimer=setTimeout(()=>{headlineIndex=(headlineIndex+1)%activeHeadlines().length;const el=$('#rotating-headline');if(el){el.classList.remove('headline-in');el.classList.add('headline-out');setTimeout(()=>{if(!el.isConnected)return;el.textContent=activeHeadlines()[headlineIndex];el.classList.remove('headline-out');el.classList.add('headline-in')},180)}scheduleHeadline()},3000)}
function syncHeadline(){const role=S.user?.role==='owner'?'owner':'renter';if(role!==headlineRole){headlineRole=role;headlineIndex=0;scheduleHeadline()}const el=$('#rotating-headline');if(el)el.textContent=activeHeadlines()[headlineIndex]}
function home(){const f=S.f;return `<section class="hero"><div class="hero-content"><p class="hero-eyebrow">GoRent · Make every moment memorable</p><h1 id="rotating-headline" class="headline-in">${esc(renterHeadlines[headlineIndex])}</h1><p class="hero-subtitle">Find a beautiful ride for the moments that matter.</p><div class="sb"><label class="f search-field">Search a car or city<input id="car-search" data-f="q" value="${esc(f.q)}" placeholder="Car name, brand or city" autocomplete="off"></label><label class="f">Pickup<input data-f="from" type="date" min="${date(0)}" value="${f.from}"></label><label class="f">Return<input data-f="to" type="date" min="${date(1)}" value="${f.to}"></label><button class="btn sun" data-a="search">Explore cars</button></div><p class="hero-note">Direct owner requests <span>✦</span> Google Maps pickup route <span>✦</span> Pay at handover</p></div><a class="scroll-cue" href="#results">Scroll to explore <span>↓</span></a></section><section class="catalog"><div class="catalog-heading"><p class="hero-eyebrow">Curated for your next drive</p><h2>Find your perfect car</h2></div><div class="flt"><input data-f="city" value="${esc(f.city)}" placeholder="Filter by city"><select data-f="fuel"><option value="">Any fuel</option>${opts(['Petrol','Diesel','CNG','Electric'],f.fuel)}</select><select data-f="transmission"><option value="">Any gearbox</option>${opts(['Manual','Automatic'],f.transmission)}</select><select data-f="category"><option value="">Any type</option>${opts(['Hatchback','Sedan','SUV','MUV','EV'],f.category)}</select><label class="rg">Max \u20B9/day <input data-f="max_price" type="number" min="1" value="${esc(f.max_price)}" placeholder="Any"></label><select data-f="sort"><option value="rating">Top rated</option><option value="price" ${f.sort==='price'?'selected':''}>Lowest price</option><option value="newest" ${f.sort==='newest'?'selected':''}>Newest</option></select></div><div id="results"><div class="rh"><h2>${S.cars.length} car${S.cars.length===1?'':'s'} available</h2></div>${S.cars.length?`<div class="grid">${S.cars.map(c=>`<button class="cc car-button" data-a="car" data-id="${c.id}"><div class="vehicle-art">🚗</div><div class="cb"><h3>${esc(c.brand)} ${esc(c.name)}</h3><div class="sp">${esc(c.fuel)} · ${esc(c.transmission)} · ${c.seats} seats</div><div class="sp">${esc(c.city)} · ${esc(c.owner_name)}</div><div class="pr">${money(c.price_per_day)}<small> /day</small></div>${chip('published')}</div></button>`).join('')}</div>`:'<div class="box">No cars found. Try another car, city, date, or filter.</div>'}</div></section>`}
const rentedStatuses=new Set(['active','returned','completed','disputed']);
function wasRented(booking){return rentedStatuses.has(booking.status)||booking.events?.some(event=>rentedStatuses.has(event.to_status))}
function rentalStartedAt(booking){return booking.events?.find(event=>event.to_status==='active')?.at||booking.created_at}
function ownerCarName(car){const brand=String(car.brand||'').trim(),model=String(car.name||'').trim();return !model||(/^\d{4}$/.test(model)&&Number(model)>=1900&&Number(model)<=2100)||brand.toLowerCase().endsWith(model.toLowerCase())?brand:`${brand} ${model}`}
function ownerCarState(car){const bookings=S.bookings.filter(b=>Number(b.vehicle)===Number(car.id));if(bookings.some(b=>b.status==='active'))return 'On rent';if(bookings.some(b=>b.status==='confirmed'))return 'Reserved';if(car.status!=='published')return title(car.status);return 'Available'}
function ownerCarCard(car){const bookings=S.bookings.filter(b=>Number(b.vehicle)===Number(car.id));return `<article class="owner-car-card" data-car-id="${car.id}"><div class="vehicle-art owner-car-art">&#128663;</div><div class="owner-car-copy"><div class="owner-card-top"><span class="history-kicker">${esc(car.city)}</span>${chip(ownerCarState(car))}</div><h2>${esc(ownerCarName(car))}</h2><p class="mut sm">${esc(car.category)} &middot; ${esc(car.fuel)} &middot; ${esc(car.transmission)} &middot; ${car.seats} seats</p><div class="owner-card-metrics"><div><b>${money(car.price_per_day)}</b><span>per day</span></div><div><b>${bookings.length}</b><span>requests</span></div><div><b>${bookings.filter(wasRented).length}</b><span>rentals</span></div></div><div class="act"><label class="btn ghost s photo-edit">${car.image_url?'Change photo':'Add photo'}<input type="file" data-car-image="${car.id}" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" hidden></label><button class="btn ghost s" data-a="edit-car" data-id="${car.id}">Edit listing</button><button class="btn ghost s" data-a="view-requests">View requests</button>${car.status==='draft'?`<button class="btn s" data-a="${S.user.identity_can_list?'publish-car':'verify-owner'}" data-id="${car.id}">${S.user.identity_can_list?'List car':'Verify ID to list'}</button>`:''}${car.status==='unlisted'&&!bookings.some(b=>['confirmed','active','returned','disputed'].includes(b.status))?`<button class="btn s" data-a="relist-car" data-id="${car.id}">Relist car</button>`:''}</div><div id="owner-edit-${car.id}"></div></div></article>`}
function ownerCarsMarkup(cars){return cars.length?`<div class="owner-car-grid">${cars.map(ownerCarCard).join('')}</div>`:`<div class="box owner-empty"><h2>No matching cars</h2><p class="mut">Try another search or list a new car.</p><button class="btn s" data-a="${S.user.identity_can_list?'new-car':'verify-owner'}">${S.user.identity_can_list?'List a car':'Verify ID to list'}</button></div>`}
function ownerMatches(car){const q=S.ownerQuery.trim().toLowerCase(),name=`${car.brand} ${car.name} ${car.city} ${car.category}`.toLowerCase();if(q&&!name.includes(q))return false;const status=S.ownerStatus;if(status==='all')return true;if(status==='rented')return S.bookings.some(b=>Number(b.vehicle)===Number(car.id)&&wasRented(b));return ownerCarState(car).toLowerCase().replace(' ','_')===status}
function ownerHome(){const requests=S.bookings.filter(b=>b.status==='requested').length,active=S.bookings.filter(b=>b.status==='active').length,rentals=S.bookings.filter(wasRented),value=rentals.reduce((sum,b)=>sum+Number(b.amount||0),0);return `<section class="hero owner-hero"><div class="hero-content"><p class="hero-eyebrow">GoRent for car owners</p><h1 id="rotating-headline" class="headline-in">${esc(ownerHeadlines[headlineIndex])}</h1><p class="hero-subtitle">Manage your cars, review requests, and share pickup details in one place.</p><div class="owner-action-bar"><div><b>Rent out your next car</b><span>List your car and receive rental requests directly.</span></div><button class="btn sun" data-a="${S.user.identity_can_list?'new-car':'verify-owner'}">${S.user.identity_can_list?'List your car':'Verify ID to list'}</button><button class="btn ghost" data-a="view-requests">View requests</button></div><p class="hero-note">Your cars <span>&#10022;</span> Your approval <span>&#10022;</span> Your pickup location</p></div><a class="scroll-cue" href="#owner-overview">Your overview <span>&darr;</span></a></section><section id="owner-overview" class="owner-overview"><div class="catalog-heading"><p class="hero-eyebrow">Owner workspace</p><h2>Your business at a glance</h2></div><div class="owner-kpis"><div class="owner-kpi"><b>${S.mine.length}</b><span>Listed cars</span></div><div class="owner-kpi"><b>${requests}</b><span>New requests</span></div><div class="owner-kpi"><b>${active}</b><span>Cars on rent</span></div><div class="owner-kpi"><b>${money(value)}</b><span>Rental value tracked</span></div></div><div class="owner-shortcuts"><div class="box"><h3>Manage your fleet</h3><p class="mut">See each car's status, requests and rental count.</p><button class="btn ghost s" data-nav="explore">Explore your cars</button></div><div class="box"><h3>Rental activity</h3><p class="mut">Review cars that have been handed over for rent.</p><button class="btn ghost s" data-nav="history">Rental history</button></div></div></section>`}
function ownerExplore(){return `<section class="owner-section"><div class="owner-section-head"><div><p class="history-kicker">Owner fleet</p><h1>Your listed cars</h1><p class="mut">Every car shown here belongs to your account.</p></div><button class="btn" data-a="${S.user.identity_can_list?'new-car':'verify-owner'}">${S.user.identity_can_list?'List another car':'Verify ID to list'}</button></div>${ownerCarsMarkup(S.mine)}</section>`}
function ownerSearch(){return `<section class="owner-section"><div class="owner-section-head"><div><p class="history-kicker">Search your fleet</p><h1>Find your car</h1><p class="mut">Search only the cars you uploaded for rent.</p></div><button class="btn ghost s" data-a="${S.user.identity_can_list?'new-car':'verify-owner'}">${S.user.identity_can_list?'Add a car':'Verify ID to list'}</button></div><div class="owner-search-bar"><label>Car name or city<input id="owner-search" value="${esc(S.ownerQuery)}" placeholder="Search your listed cars" autocomplete="off"></label><label>Rental status<select id="owner-status"><option value="all" ${S.ownerStatus==='all'?'selected':''}>All cars</option><option value="available" ${S.ownerStatus==='available'?'selected':''}>Available</option><option value="reserved" ${S.ownerStatus==='reserved'?'selected':''}>Reserved</option><option value="on_rent" ${S.ownerStatus==='on_rent'?'selected':''}>On rent</option><option value="rented" ${S.ownerStatus==='rented'?'selected':''}>Rented before</option><option value="unlisted" ${S.ownerStatus==='unlisted'?'selected':''}>Unlisted</option><option value="draft" ${S.ownerStatus==='draft'?'selected':''}>Saved drafts</option></select></label></div><div id="owner-search-results">${ownerCarsMarkup(S.mine.filter(ownerMatches))}</div></section>`}
function ownerHistory(){const rentals=S.bookings.filter(wasRented).sort((a,b)=>new Date(rentalStartedAt(b))-new Date(rentalStartedAt(a))),value=rentals.reduce((sum,b)=>sum+Number(b.amount||0),0);return `<section class="owner-section"><div class="owner-section-head"><div><p class="history-kicker">Rental history</p><h1>Cars rented out</h1><p class="mut">Accepted requests are added here once a car is handed over.</p></div><div class="owner-history-total"><b>${money(value)}</b><span>Total booking value</span></div></div>${rentals.length?`<div class="owner-rental-list">${rentals.map(b=>`<article class="owner-rental-card"><div><span class="history-kicker">${esc(b.code)}</span><h2>${esc(b.vehicle_name)}</h2><p class="mut">Rented by ${esc(b.customer_name||'Renter')}</p><p class="mut sm">${esc(bookingPeriod(b))} &middot; Rented ${esc(requestTime(rentalStartedAt(b)))}</p></div><div class="owner-rental-side">${chip(b.status)}<b>${money(b.amount)}</b></div></article>`).join('')}</div>`:'<div class="history-empty"><span>&#128663;</span><h2>No rentals yet</h2><p class="mut">When a confirmed car is handed over, that rental appears here.</p><button class="btn" data-nav="explore">View your cars</button></div>'}</section>`}
const historyKey=()=>`gorent_search_history:${S.user?.email||'guest'}`;
function getHistory(){try{const value=JSON.parse(localStorage.getItem(historyKey())||'[]');return Array.isArray(value)?value:[]}catch{return []}}
function saveSearch(){const filters={};for(const key of ['q','city','fuel','transmission','category','max_price','sort','from','to'])filters[key]=S.f[key];const searches=getHistory().filter(item=>JSON.stringify(item.filters)!==JSON.stringify(filters));searches.unshift({filters,at:new Date().toISOString()});localStorage.setItem(historyKey(),JSON.stringify(searches.slice(0,10)))}
function historyView(){
  const entries=getHistory();
  const rows=entries.map((item,index)=>{const f=item.filters||{},parts=[f.city,f.fuel,f.transmission,f.category].filter(Boolean);return `<article class="history-item"><div class="history-mark">⌕</div><div class="history-copy"><h2>${esc(f.q||f.city||'All cars')}</h2><p>${esc(parts.join(' · ')||'All locations')} · ${esc(f.from||'')} to ${esc(f.to||'')}</p><time>${new Date(item.at).toLocaleString()}</time></div><div class="history-actions"><button class="btn s" data-history="repeat" data-index="${index}">Search again</button><button class="btn ghost s" data-history="remove" data-index="${index}" aria-label="Remove search">Remove</button></div></article>`}).join('');
  const content=entries.length?`<div class="history-list">${rows}</div>`:'<div class="history-empty"><span>⌕</span><h2>No searches yet</h2><p class="mut">Search for a car or city and it will appear here.</p><button class="btn" data-nav="search">Start searching</button></div>';
  return `<section class="history-page"><div class="history-heading"><div><p class="history-kicker">Your recent journeys</p><h1>Search history</h1><p class="mut">Pick up where you left off. Saved in this browser${S.user?' for your account':''}.</p></div>${entries.length?'<button class="btn ghost s" data-history="clear">Clear history</button>':''}</div>${content}</section>`;
}
function hourValue(value){return value?new Date(value).toISOString():''}
function bookingPeriod(b){return b.booking_type==='hourly'?`${requestTime(b.start_at)} to ${requestTime(b.end_at)} - hourly`: `${b.start} to ${b.end} - daily`}
function car(){const c=S.car;if(!c)return '<div class="box">Car unavailable.</div>';const f=S.f,days=Math.max(0,Math.round((new Date(f.to)-new Date(f.from))/86400000)),hourly=f.bookingType==='hourly',hours=f.hourFrom&&f.hourTo?Math.max(0,Math.ceil((new Date(f.hourTo)-new Date(f.hourFrom))/3600000)):0,hourRate=Math.ceil(c.price_per_day/24);return `<div class="pg"><button class="btn ghost s" data-a="go" data-id="home">&larr; Back to cars</button></div><div class="dt"><div><div class="vehicle-art large">&#128663;</div><h1>${esc(c.brand)} ${esc(c.name)}</h1><div class="specs"><div>Fuel<b>${esc(c.fuel)}</b></div><div>Gearbox<b>${esc(c.transmission)}</b></div><div>Seats<b>${c.seats}</b></div><div>Year<b>${c.year}</b></div></div><div class="box"><b>${esc(c.owner_name)}</b><p class="mut sm">Pickup in ${esc(c.city)}. Exact location shared after owner accepts.</p></div><div class="box"><b>About this car</b><p>${esc(c.description||'Message the owner after requesting.')}</p><p class="mut sm">Rental length: hourly (1-${c.max_days*24} hours) or ${c.min_days}-${c.max_days} days &middot; Deposit: ${money(c.deposit)}</p></div></div><aside class="panel"><div class="pr">${money(c.price_per_day)}<small> /day</small></div><p class="mut sm">Hourly rate: ${money(hourRate)}/hour (rounded up from daily price)</p><label class="f">Rent for<select id="booking-type"><option value="daily" ${hourly?'':'selected'}>Days</option><option value="hourly" ${hourly?'selected':''}>Hours</option></select></label>${hourly?`<div class="two"><label class="f">Pickup date & time<input data-f="hourFrom" type="datetime-local" value="${esc(f.hourFrom)}"></label><label class="f">Return date & time<input data-f="hourTo" type="datetime-local" value="${esc(f.hourTo)}"></label></div>`:`<div class="two"><label class="f">Pickup<input data-f="from" type="date" min="${date(0)}" value="${f.from}"></label><label class="f">Return<input data-f="to" type="date" min="${date(1)}" value="${f.to}"></label></div>`}<div class="ln"><span>Rental (${hourly?`${hours} hour${hours===1?'':'s'}`:`${days} days`})</span><b>${money(hourly?hours*hourRate:days*c.price_per_day)}</b></div><p class="mut sm">Owner will respond to your request directly. Pay at handover.</p>${S.user?.role==='customer'?`<label class="f">Your ID type<select id="renter-id-type"><option value="pan">PAN card</option><option value="aadhaar">Masked Aadhaar</option><option value="driving_licence">Driving licence</option><option value="passport">Passport</option><option value="voter_id">Voter ID</option><option value="student_id">Student ID</option><option value="employee_id">Employee ID</option><option value="other">Other ID</option></select></label><label class="f">Upload ID (JPG, PNG or PDF; max 5 MB)<input id="renter-id-file" type="file" accept=".jpg,.jpeg,.png,.pdf"></label><label class="chk"><input id="renter-id-masked" type="checkbox"> If using Aadhaar, its first eight digits are hidden.</label><label class="chk"><input id="renter-id-consent" type="checkbox"> I agree to share this ID privately with the car owner for this request.</label><button class="btn" data-a="book">Request this car</button>`:S.user?'<p class="mut sm">Sign in with a renter account to request.</p>':'<button class="btn" data-a="go" data-id="login">Sign in to request</button>'}</aside></div>`}
function requestTime(value){const d=new Date(value);return Number.isNaN(d.getTime())?'':d.toLocaleString('en-IN',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'})}
function cashState(b){if(b.payment_status==='paid_at_handover'&&b.renter_paid_at&&b.owner_received_at)return 'Cash handover confirmed by both parties';if(b.renter_paid_at&&!b.owner_received_at)return 'Renter marked cash paid. Waiting for owner confirmation.';if(b.payment_status==='unverified_legacy')return 'Older booking: cash handover has not been confirmed in the app.';return 'Cash payment not recorded yet.'}
function paymentControls(b,owner){if(!['active','returned','completed'].includes(b.status))return '';return `${!owner&&!b.renter_paid_at?`<button class="btn s" data-a="cash-payment" data-payment-action="mark_paid" data-id="${b.id}">I paid cash</button>`:''}${owner&&b.renter_paid_at&&!b.owner_received_at?`<button class="btn s" data-a="cash-payment" data-payment-action="confirm_received" data-id="${b.id}">Confirm cash received</button>`:''}${b.renter_paid_at&&b.owner_received_at?`<button class="btn ghost s" data-extra="receipt" data-id="${b.id}">Cash receipt</button>`:''}`}
function bookingActions(b,owner,moves){return (moves[b.status]||[]).map(next=>next==='cancelled'&&b.status==='confirmed'?(b.can_cancel_confirmed?`<button class="btn s red" data-a="show-cancel" data-id="${b.id}">Cancel booking</button>`:''):`<button class="btn s ${['rejected','cancelled'].includes(next)?'red':''}" data-a="transition" data-id="${b.id}" data-status="${next}" ${next==='returned'&&b.payment_status!=='paid_at_handover'?'disabled title="Confirm cash payment before return"':''}>${title(next)}</button>`).join('')}
function row(b){
  const owner=S.user?.role==='owner';
  const moves=owner?{requested:['rejected'],confirmed:['active','cancelled'],active:['returned','disputed'],returned:['completed','disputed']}:{requested:['cancelled'],confirmed:['cancelled']};
  const renterUpload=!owner&&b.status==='requested'?`<form class="box renter-id-form" data-id="${b.id}"><h3>${b.identity_submitted?'Replace your ID':'Upload your ID before the owner can accept'}</h3><label>ID type<select name="id_type"><option value="pan">PAN card</option><option value="aadhaar">Masked Aadhaar</option><option value="driving_licence">Driving licence</option><option value="passport">Passport</option><option value="voter_id">Voter ID</option><option value="student_id">Student ID</option><option value="employee_id">Employee ID</option><option value="other">Other ID</option></select></label><label>ID document<input name="id_document" type="file" accept=".jpg,.jpeg,.png,.pdf" required></label><label class="chk"><input name="masked_aadhaar" type="checkbox" value="true"> If using Aadhaar, its first eight digits are hidden.</label><label class="chk"><input name="consent" type="checkbox" value="true" required> Share this ID privately with the owner.</label><button class="btn s">${b.identity_submitted?'Replace ID':'Upload ID'}</button></form>`:'';
  return `<div class="row booking-row"><div class="rt"><div class="gr"><b>${esc(b.vehicle_name)}</b><div class="mut sm">${esc(b.code)} &middot; ${esc(bookingPeriod(b))} &middot; ${owner?`${esc(b.customer_name||'Renter')} &middot; `:''}${money(b.amount)}</div><div class="mut sm">Requested: ${esc(requestTime(b.created_at))}</div></div>${chip(b.status)}</div><p class="mut sm">Renter ID: ${b.identity_submitted?esc(title(b.id_type||'submitted')):'Not submitted yet'}</p>${b.pickup_route_url?`<p class="pickup-summary">Pickup: ${esc(b.pickup_address)} <a class="btn ghost s" href="${esc(b.pickup_route_url)}" target="_blank" rel="noopener noreferrer">Open Google Maps route &nearr;</a></p>`:''}${['confirmed','active','returned','completed'].includes(b.status)?`<div class="cash-status"><b>Cash at handover</b><span>${esc(cashState(b))}</span></div>`:''}${b.status==='cancelled'&&b.cancellation_reason?`<p class="mut sm">Cancellation reason: ${esc(b.cancellation_reason)}</p>`:''}<div class="act">${owner&&b.identity_submitted&&!['rejected','cancelled'].includes(b.status)?`<button class="btn ghost s" data-a="renter-id" data-id="${b.id}">View renter ID</button>`:''}${owner&&b.status==='requested'&&b.identity_submitted&&b.identity_reviewed?`<button class="btn s" data-a="show-pickup" data-id="${b.id}">Accept & set pickup</button>`:''}${bookingActions(b,owner,moves)}${paymentControls(b,owner)}</div>${owner&&b.status==='requested'&&b.identity_submitted&&!b.identity_reviewed?'<p class="mut sm">Open the renter ID to enable acceptance.</p>':''}${renterUpload}<div id="pickup-${b.id}"></div><div id="cancel-${b.id}"></div><div class="act"><button class="btn ghost s" data-extra="messages" data-id="${b.id}">Messages</button>${b.status==='completed'&&!owner?`<button class="btn ghost s" data-extra="review" data-id="${b.id}">Write review</button>`:''}</div><div id="booking-extra-${b.id}"></div></div>`
}
function trips(){return `<div class="pg"><h1>My trips</h1></div>${S.bookings.length?S.bookings.map(row).join(''):'<div class="box">No trips yet. Explore cars to make your first request.</div>'}`}
function ownerIdentitySection(){
  const ready=S.user.identity_can_list;
  return `<div class="dashboard-section-head"><div><p class="history-kicker">Account safety</p><h2>Owner ID check</h2><p class="mut">Complete this step before publishing a new car.</p></div>${chip(ready?(S.user.identity_local_demo?'local_check':'verified'):'not_submitted')}</div><div class="dashboard-card identity-panel">${ready?`<div class="dashboard-success"><span>✓</span><div><h3>ID file check complete</h3><p class="mut sm">${S.user.identity_local_demo?'This is a local file check. Document authenticity has not been verified.':'Your identity is verified.'}</p></div></div>`:`<h3>Upload an identity document</h3><p class="mut sm">Choose a government, student, employee or other ID. Your document stays private and is never shown to renters.</p>${S.user.identity_local_demo?`<p class="mut sm dashboard-note">Local test only: file format is checked, not authenticity. Mask the first eight Aadhaar digits.</p><form id="identity-form" class="dashboard-form"><label>ID type<select name="document_type" required><option value="pan">PAN card</option><option value="aadhaar">Masked Aadhaar</option><option value="driving_licence">Driving licence</option><option value="passport">Passport</option><option value="voter_id">Voter ID</option><option value="student_id">Student ID</option><option value="employee_id">Employee ID</option><option value="other">Other ID</option></select></label><label>ID document (JPG, PNG or PDF; max 5 MB)<input name="document" type="file" accept=".jpg,.jpeg,.png,.pdf" required></label><label class="chk"><input name="masked_aadhaar" type="checkbox" value="true"> If using Aadhaar, its first eight digits are hidden.</label><label class="chk"><input name="consent" type="checkbox" value="true" required> I consent to private local processing of this document.</label><button class="btn">Complete ID check</button></form>`:'<p class="dashboard-note">Identity provider is not connected. Listing will unlock when verification is available.</p>'}`}</div>`
}
function ownerListingSection(){return `<div class="dashboard-section-head"><div><p class="history-kicker">Grow your fleet</p><h2>Add a car</h2><p class="mut">Enter accurate details so renters know exactly what they are requesting.</p></div></div>${!S.user.identity_can_list?`<div class="dashboard-alert">Complete your owner ID check before listing. <button class="link-button" data-owner-panel="identity">Go to ID check →</button></div>`:''}<form id="vehicle-form" class="dashboard-card dashboard-form"><div class="dashboard-form-heading"><span>01</span><div><h3>Car details</h3><p class="mut sm">Name, location and specifications</p></div></div><div class="dashboard-form-grid"><label>Brand<input name="brand" placeholder="e.g. Mahindra" required></label><label>Model<input name="name" placeholder="e.g. Thar" required></label><label>City<input name="city" placeholder="Pickup city" required></label><label>Category<select name="category">${opts(['Hatchback','Sedan','SUV','MUV','EV'])}</select></label><label>Fuel<select name="fuel">${opts(['Petrol','Diesel','CNG','Electric'])}</select></label><label>Transmission<select name="transmission">${opts(['Manual','Automatic'])}</select></label><label>Seats<input name="seats" type="number" min="1" max="20" value="5" required></label><label>Year<input name="year" type="number" min="1990" max="2100" value="${new Date().getFullYear()}" required></label></div><div class="dashboard-form-heading"><span>02</span><div><h3>Pricing and photo</h3><p class="mut sm">Renters can book by day or hour</p></div></div><div class="dashboard-form-grid"><label>Price per day (₹)<input name="price_per_day" type="number" min="1" placeholder="Daily rental price" required></label><label>Deposit (₹)<input name="deposit" type="number" min="0" value="0" required></label><label class="dashboard-span">Car photo (JPG, PNG, WebP; max 10 MB)<input name="image" type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"></label><label class="dashboard-span">Description<textarea name="description" rows="4" placeholder="Condition, features and any useful pickup details"></textarea></label></div><div class="dashboard-form-footer"><p class="mut sm">Your car goes live after you submit. You control each rental request.</p><button class="btn" ${S.user.identity_can_list?'':'disabled title="Complete owner ID check first"'}>List car now</button><button class="btn ghost" type="submit" value="draft">Save to My cars</button></div></form>`}
function ownerFleetSection(){return `<div class="dashboard-section-head"><div><p class="history-kicker">Your fleet</p><h2>My cars</h2><p class="mut">Save your cars here, then list them when you are ready. Manage photos, pricing and availability.</p></div><button class="btn s" data-a="new-car">Add a car</button></div>${S.mine.length?`<div class="owner-car-grid">${S.mine.map(ownerCarCard).join('')}</div>`:`<div class="dashboard-empty"><span>🚗</span><h3>No cars saved yet</h3><p class="mut">Save a car here first, then list it whenever you are ready.</p><button class="btn" data-a="new-car">Add a car</button></div>`}`}
function ownerRequestsSection(){const pending=S.bookings.filter(b=>b.status==='requested'),others=S.bookings.filter(b=>b.status!=='requested');return `<div class="dashboard-section-head"><div><p class="history-kicker">Rental inbox</p><h2>Requests</h2><p class="mut">Review renter IDs and decide which requests to accept.</p></div>${chip(`${pending.length} new`)}</div>${pending.length?`<div class="dashboard-list">${pending.map(row).join('')}</div>`:`<div class="dashboard-empty compact"><h3>All caught up</h3><p class="mut">New rental requests will appear here.</p></div>`}${others.length?`<div class="dashboard-subhead"><h3>Other requests</h3><span class="mut sm">${others.length} total</span></div><div class="dashboard-list">${others.map(row).join('')}</div>`:''}`}
function ownerOverviewSection(){const pending=S.bookings.filter(b=>b.status==='requested').length,active=S.bookings.filter(b=>['confirmed','active','returned'].includes(b.status)).length,listed=S.mine.filter(c=>c.status==='published').length;return `<div class="dashboard-section-head"><div><p class="history-kicker">Owner workspace</p><h2>Overview</h2><p class="mut">Your cars and rental activity in one place.</p></div><button class="btn s" data-a="new-car">Add a car</button></div><div class="dashboard-metrics"><div><span>Live listings</span><strong>${listed}</strong><small>Visible to renters</small></div><div><span>New requests</span><strong>${pending}</strong><small>Need your review</small></div><div><span>Reserved or on rent</span><strong>${active}</strong><small>Hidden from Explore</small></div><div><span>Saved drafts</span><strong>${S.mine.filter(c=>c.status==='draft').length}</strong><small>Ready to list anytime</small></div></div><div class="dashboard-quick-grid"><article class="dashboard-card"><span class="dashboard-card-icon">↗</span><h3>Manage your cars</h3><p class="mut sm">Edit details, update photos or relist a car after a rental.</p><button class="btn ghost s" data-owner-panel="cars">View my cars</button></article><article class="dashboard-card"><span class="dashboard-card-icon">✉</span><h3>Rental requests</h3><p class="mut sm">Open renter IDs, respond and set pickup locations.</p><button class="btn ghost s" data-owner-panel="requests">Open requests</button></article></div>${!S.user.identity_can_list?`<div class="dashboard-alert">Complete your ID check to publish a car. <button class="link-button" data-owner-panel="identity">Start ID check →</button></div>`:''}`}
function owner(){
  if(S.user?.role!=='owner')return '<div class="box">Owner access required.</div>';
  const items=[['overview','Overview','◫'],['requests','Requests','✉'],['cars','My cars','🚗'],['add','Add a car','＋'],['identity','ID check','◈']];
  const panels={overview:ownerOverviewSection,requests:ownerRequestsSection,cars:ownerFleetSection,add:ownerListingSection,identity:ownerIdentitySection};
  const current=panels[S.ownerPanel]?S.ownerPanel:'overview';
  return `<div class="owner-dashboard"><aside class="owner-dashboard-sidebar"><div class="owner-sidebar-brand"><span class="owner-sidebar-icon">G</span><div><b>${esc(S.user.company_name||S.user.first_name||'Car owner')}</b><small>Owner account</small></div></div><p class="owner-sidebar-label">WORKSPACE</p><nav aria-label="Owner dashboard sections">${items.map(([key,label,icon])=>`<button type="button" data-owner-panel="${key}" class="${current===key?'selected':''}" ${current===key?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}${key==='requests'&&S.bookings.some(b=>b.status==='requested')?`<em>${S.bookings.filter(b=>b.status==='requested').length}</em>`:''}</button>`).join('')}</nav><div class="owner-sidebar-help"><b>Need a hand?</b><p>Review requests before accepting. Set pickup details after checking the renter's ID.</p></div></aside><section class="owner-dashboard-main">${panels[current]()}</section></div>`;
}
function auth(mode){const r=mode==='register';return `<div class="auth-card box"><h1>${r?'Create account':'Sign in'}</h1><form id="auth-form" data-mode="${mode}">${r?'<label>Name<input name="first_name" required></label>':''}<label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="8" required></label>${r?'<label>Account type<select name="role"><option value="customer">Renter</option><option value="owner">Car owner</option></select></label><label>Phone<input name="phone" type="tel"></label><label>Business name (owners)<input name="company_name"></label>':''}<button class="btn">${r?'Create account':'Sign in'}</button></form><p class="sm"><button class="link-button" data-a="go" data-id="${r?'login':'register'}">${r?'Already registered? Sign in':'New here? Create account'}</button></p></div>`}
const login=()=>auth('login'),register=()=>auth('register');
async function action(b){const {a,id,status}=b.dataset;try{if(a==='go'){S.view=id;render();scrollTo(0,0)}if(a==='verify-owner'){S.view='owner';S.ownerPanel='identity';render();scrollTo(0,0)}if(a==='new-car'){S.view='owner';S.ownerPanel='add';render();scrollTo(0,0)}if(a==='view-requests'){S.view='owner';S.ownerPanel='requests';render();scrollTo(0,0)}if(a==='show-identity'){S.view='owner';S.ownerPanel='identity';render();$('#identity-form')?.elements.document_type?.focus({preventScroll:true})}if(a==='edit-car'){const car=S.mine.find(c=>Number(c.id)===Number(id)),target=$(`#owner-edit-${id}`);if(!car||!target)throw Error('Car not found');target.innerHTML=`<form class="box owner-edit-form" data-id="${car.id}"><h3>Edit ${esc(ownerCarName(car))}</h3><div class="owner-edit-fields"><label>Price/day<input name="price_per_day" type="number" min="1" required value="${car.price_per_day}"></label><label>Deposit<input name="deposit" type="number" min="0" required value="${car.deposit}"></label><label>City<input name="city" required value="${esc(car.city)}"></label><label>Pickup address<input name="address" value="${esc(car.address||'')}"></label></div><label>Description<textarea name="description">${esc(car.description||'')}</textarea></label><label>New photo (optional)<input name="image" type="file" accept=".jpg,.jpeg,.png,.webp"></label><button class="btn s">Save changes</button></form>`;target.scrollIntoView({behavior:'smooth',block:'center'})}if(a==='publish-car'){await api(`vehicles/${id}/publish`,{method:'POST'});await refresh();toast('Saved car is now live in Explore')}if(a==='relist-car'){await api(`vehicles/${id}/relist`,{method:'POST'});await refresh();toast('Car is listed again and visible to renters')}if(a==='logout'){await api('auth/logout',{method:'POST'});signout()}if(a==='search'){await refresh();$('#results')?.scrollIntoView({behavior:'smooth'})}if(a==='car'){S.car=await api(`vehicles/${id}`,{auth:false});S.view='car';render();scrollTo(0,0)}if(a==='book'){const f=S.f,file=$('#renter-id-file')?.files[0];if(f.bookingType==='hourly'){const duration=(new Date(f.hourTo)-new Date(f.hourFrom))/3600000;if(!f.hourFrom||!f.hourTo||new Date(f.hourFrom)<=new Date()||duration<1||duration>S.car.max_days*24)throw Error(`Choose 1 to ${S.car.max_days*24} hours starting in the future.`)}else if(f.from<date(0)||f.to<=f.from)throw Error('Choose valid dates.');if(!file||!$('#renter-id-consent')?.checked)throw Error('Upload your ID and agree to share it with the owner.');const body=new FormData();for(const [k,v] of Object.entries({vehicle:S.car.id,booking_type:f.bookingType,...(f.bookingType==='hourly'?{start_at:hourValue(f.hourFrom),end_at:hourValue(f.hourTo)}:{start:f.from,end:f.to}),id_type:$('#renter-id-type').value,consent:'true',id_document:file}))body.append(k,v);if($('#renter-id-masked').checked)body.append('masked_aadhaar','true');await api('bookings',{method:'POST',body});S.view='trips';await refresh();toast('Request and ID sent privately to the owner')}if(a==='show-cancel'){const target=$(`#cancel-${id}`);if(target){target.innerHTML=`<form class="box cancel-form" data-id="${id}"><h3>Cancel booking</h3><p class="mut sm">Confirmed bookings can be cancelled only before pickup. Explain the reason to the other party.</p><label>Reason<textarea name="reason" maxlength="500" required placeholder="Why are you cancelling?"></textarea></label><button class="btn red s">Confirm cancellation</button></form>`;target.scrollIntoView({behavior:'smooth',block:'center'})}}if(a==='cash-payment'){const paymentAction=b.dataset.paymentAction;const prompt=paymentAction==='mark_paid'?'Confirm you handed the full rental amount in cash to the car owner?':'Confirm you received the full rental amount in cash from the renter?';if(!window.confirm(prompt))return;await api(`bookings/${id}/payment`,{method:'POST',body:{action:paymentAction}});await refresh();toast(paymentAction==='mark_paid'?'Cash marked paid. Waiting for owner confirmation.':'Cash received. Receipt is now available.')}if(a==='transition'){await api(`bookings/${id}/transition`,{method:'POST',body:{status}});await refresh();toast(`Request ${title(status)}`)}if(a==='renter-id'){const tab=window.open('','_blank');try{const response=await fetch(`/api/bookings/${id}/document`,{headers:{Authorization:`Token ${S.token}`}});if(!response.ok)throw Error('Could not open renter ID');const url=URL.createObjectURL(await response.blob());if(tab)tab.location.href=url;else window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000);await refresh();toast('Renter ID opened. You can now accept the request.')}catch(error){tab?.close();throw error}}if(a==='show-pickup'){const target=$(`#pickup-${id}`);target.innerHTML=`<form class="box pickup-form" data-id="${id}"><h3>Pickup location</h3><p class="mut sm">Enter a precise address, or use your current location. The renter sees it after you accept.</p><label>Pickup address<input name="pickup_address" maxlength="250" required placeholder="Street, landmark, city"></label><input name="pickup_lat" type="hidden"><input name="pickup_lng" type="hidden"><div class="act"><button type="button" class="btn ghost s" data-a="locate" data-id="${id}">Use my location</button><a class="btn ghost s" href="https://www.google.com/maps" target="_blank" rel="noopener noreferrer">Find on Google Maps</a><button class="btn s">Accept request</button></div></form>`;target.scrollIntoView({behavior:'smooth',block:'center'})}if(a==='locate'){if(!navigator.geolocation)throw Error('Location is not supported in this browser. Enter the address manually.');navigator.geolocation.getCurrentPosition(async position=>{const form=$(`#pickup-${id} form`);if(!form)return;const lat=position.coords.latitude.toFixed(6),lng=position.coords.longitude.toFixed(6);form.elements.pickup_lat.value=lat;form.elements.pickup_lng.value=lng;form.elements.pickup_address.value=`${lat}, ${lng}`;toast('Location added. Check the pickup address before accepting.')},()=>toast('Location permission denied. Enter the address manually.',true),{enableHighAccuracy:true,timeout:10000})}}catch(e){toast(e.message,true)}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-owner-panel]');if(tab){e.preventDefault();S.view='owner';S.ownerPanel=tab.dataset.ownerPanel;render();scrollTo(0,0);return}const b=e.target.closest('[data-a]');if(b){e.preventDefault();if(b.dataset.a==='go'&&b.dataset.id==='home')S.navTarget='home';if(b.dataset.a==='search'){S.navTarget='explore';S.f.q=$('#car-search')?.value.trim()||'';saveSearch()}action(b)}});
document.addEventListener('change',async e=>{if(e.target.id==='booking-type'){S.f.bookingType=e.target.value;render();return}if(e.target.dataset.f){S.f[e.target.dataset.f]=e.target.value;if(e.target.dataset.f==='q')return;if(['hourFrom','hourTo'].includes(e.target.dataset.f)){render();return}try{if(S.view==='home')await refresh();else render()}catch(x){toast(x.message,true)}}});
document.addEventListener('change',async e=>{
  const input=e.target;if(!input.hasAttribute('data-car-image')||!input.files[0])return;
  const data=new FormData();data.append('image',input.files[0]);input.disabled=true;
  try{await api(`vehicles/${input.dataset.carImage}`,{method:'PATCH',body:data});await refresh();toast('Car photo updated')}
  catch(error){toast(error.message,true);input.disabled=false}
});
document.addEventListener('input',e=>{if(e.target.id==='owner-search'){S.ownerQuery=e.target.value;const results=$('#owner-search-results');if(results){results.innerHTML=ownerCarsMarkup(S.mine.filter(ownerMatches));paintOwnerCards()}return}if(e.target.name==='pickup_address'&&e.target.closest('.pickup-form')){const form=e.target.form;form.elements.pickup_lat.value='';form.elements.pickup_lng.value=''}});
document.addEventListener('change',e=>{if(e.target.id==='owner-status'){S.ownerStatus=e.target.value;const results=$('#owner-search-results');if(results){results.innerHTML=ownerCarsMarkup(S.mine.filter(ownerMatches));paintOwnerCards()}}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='car-search'){e.preventDefault();S.navTarget='explore';S.f.q=e.target.value.trim();saveSearch();action($('[data-a="search"]'))}});
document.addEventListener('click',async e=>{const menu=e.target.closest('#menu-toggle');if(menu){const open=$('.top').classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');return}const link=e.target.closest('[data-nav]');if(link){e.preventDefault();$('.top').classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');const destination=link.dataset.nav;S.navTarget=destination;if(S.user?.role==='owner'||['history','owner','trips'].includes(destination)){S.view=destination;render();scrollTo(0,0)}else{S.view='home';render();if(destination==='explore')$('#results')?.scrollIntoView({behavior:'smooth'});else{scrollTo(0,0);if(destination==='search')setTimeout(()=>$('#car-search')?.focus({preventScroll:true}),100)}}return}const historyButton=e.target.closest('[data-history]');if(!historyButton)return;e.preventDefault();const items=getHistory(),index=Number(historyButton.dataset.index);if(historyButton.dataset.history==='clear'){localStorage.removeItem(historyKey());render();toast('Search history cleared')}if(historyButton.dataset.history==='remove'){items.splice(index,1);localStorage.setItem(historyKey(),JSON.stringify(items));render();toast('Search removed')}if(historyButton.dataset.history==='repeat'&&items[index]){S.f={...S.f,...items[index].filters};S.view='home';S.navTarget='explore';try{await refresh();$('#results')?.scrollIntoView({behavior:'smooth'})}catch(x){toast(x.message,true)}}});
document.addEventListener('submit',async e=>{
  if(!['auth-form','vehicle-form','identity-form'].includes(e.target.id)&&!e.target.matches('.owner-edit-form'))return;
  e.preventDefault();
  const form=e.target,button=e.submitter||form.querySelector('button.btn');button.disabled=true;
  try{
    if(form.id==='auth-form'){
      const data=Object.fromEntries(new FormData(form)),register=form.dataset.mode==='register';
      const result=await api(register?'auth/register':'auth/login',{method:'POST',body:register?data:{username:data.email,password:data.password},auth:false});
      S.token=result.token;localStorage.setItem('gorent_token',result.token);S.user=result.user;
      S.view='home';
      await refresh();toast(`Welcome, ${result.user.first_name||result.user.email}`);
    }else if(form.classList.contains('owner-edit-form')){
      const data=new FormData(form);if(!data.get('image')?.size)data.delete('image');
      await api(`vehicles/${form.dataset.id}`,{method:'PATCH',body:data});await refresh();toast('Listing updated');
    }else if(form.id==='identity-form'){
      const data=new FormData(form);if(!data.get('masked_aadhaar'))data.delete('masked_aadhaar');
      S.user=await api('owner/identity',{method:'POST',body:data});S.ownerPanel='add';await refresh();toast('Local ID file check complete. You can now add a car');
    }else{
      const data=new FormData(form);if(!data.get('image')?.size)data.delete('image');
      const draft=button.value==='draft';if(draft)data.append('save_as_draft','true');await api('vehicles',{method:'POST',body:data});S.ownerPanel='cars';await refresh();toast(draft?'Car saved in My cars. List it whenever you are ready.':'Car is live now');
    }
  }catch(error){toast(error.message,true);button.disabled=false}
});
(async()=>{try{if(S.token)S.user=await api('users/me');await refresh()}catch(e){if(!S.token){try{await refresh();toast('Previous session expired. Create a new account for the fresh database.')}catch(loadError){toast(loadError.message,true);render()}}else{toast(e.message,true);render()}}})();
setInterval(async()=>{
  if(!S.user||!(S.user.role==='owner'?['home','explore','search','history','owner'].includes(S.view):S.view==='trips')||document.hidden||$('.pickup-form,.message-form,.review-form,.owner-edit-form,.cancel-form')||$('.renter-id-form:focus-within')||$('.renter-id-form input[type="file"]')?.files.length)return;
  try{
    const bookings=await api('bookings');
    const previous=JSON.stringify(S.bookings.map(b=>[b.id,b.status,b.pickup_address,b.identity_submitted,b.identity_reviewed,b.payment_status,b.renter_paid_at,b.owner_received_at]));
    const incoming=JSON.stringify(bookings.map(b=>[b.id,b.status,b.pickup_address,b.identity_submitted,b.identity_reviewed,b.payment_status,b.renter_paid_at,b.owner_received_at]));
    if(previous!==incoming){const count=S.bookings.length;S.bookings=bookings;render();if(S.view==='owner'&&bookings.length>count)toast('New rental request received')}
  }catch(error){/* Retry on the next refresh. */}
},15000);

function paintOwnerCards(){document.querySelectorAll('.owner-car-card').forEach(card=>{const car=S.mine.find(c=>Number(c.id)===Number(card.dataset.carId));paintVehicleImage(card.querySelector('.owner-car-art'),car)})}
async function enhance(){
  if(S.view==='home'){
    if(S.user?.role!=='owner')$('.hero-note')?.insertAdjacentHTML('afterend',`<p class="availability-note">Choose hourly or daily rental on a car's booking page.</p>`);
    document.querySelectorAll('.car-button').forEach((card,index)=>paintVehicleImage(card.querySelector('.vehicle-art'),S.cars[index]));
  }
  if(S.view==='car'&&S.car){
    paintVehicleImage($('.vehicle-art.large'),S.car);
    const target=$('.dt > div');
    
    const reviews=document.createElement('div');reviews.className='box';reviews.innerHTML='<h2>Reviews</h2><p class="mut sm">Loading reviews…</p>';target.append(reviews);
    try{const data=await api(`vehicles/${S.car.id}/reviews`,{auth:false});if(S.view==='car'&&S.car)reviews.innerHTML=`<h2>Reviews</h2>${data.length?data.map(r=>`<div class="ln"><b>${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</b><span>${esc(r.comment)}</span></div>`).join(''):'<p class="mut sm">No reviews yet.</p>'}`}catch(e){reviews.innerHTML='<p class="mut sm">Reviews unavailable.</p>'}
  }
  if(S.user?.role==='owner'&&['explore','search'].includes(S.view))paintOwnerCards();
  if(S.view==='owner'&&S.ownerPanel==='cars')paintOwnerCards();
}
function paintVehicleImage(container,vehicle){
  if(!container||!vehicle?.image_url)return;
  const image=document.createElement('img');image.src=vehicle.image_url;image.alt=`${vehicle.brand} ${vehicle.name}`;image.loading='lazy';container.replaceChildren(image);
}
function cashReceiptHtml(r){const period=r.booking_type==='hourly'?`${requestTime(r.start_at)} to ${requestTime(r.end_at)}`:`${r.start} to ${r.end}`;return `<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Cash receipt ${esc(r.receipt_number)}</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:700px;margin:40px auto;padding:20px;color:#172033}header{border-bottom:3px solid #2b59ff;padding-bottom:20px}h1{font-size:30px;margin:0}p{margin:6px 0}.tag{display:inline-block;padding:5px 10px;border-radius:20px;background:#d5f5e8;color:#0b7a55;font-weight:700}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}.label{font-size:12px;color:#667}.amount{font-size:28px;font-weight:800;border-top:1px solid #ccd;padding-top:18px}.note{font-size:12px;color:#667;margin-top:28px}button{padding:10px 16px;background:#2b59ff;color:#fff;border:0;border-radius:8px;cursor:pointer}@media print{button{display:none}body{margin:0}}</style></head><body><header><p>GoRent · Cash handover record</p><h1>Payment receipt</h1><p class="tag">Confirmed by renter and owner</p></header><div class="grid"><div><p class="label">Receipt reference</p><b>${esc(r.receipt_number)}</b></div><div><p class="label">Booking</p><b>${esc(r.booking_code)}</b></div><div><p class="label">Car</p><b>${esc(r.vehicle_name)}</b></div><div><p class="label">Rental period</p><b>${esc(period)}</b></div><div><p class="label">Renter</p><b>${esc(r.renter_name)}</b></div><div><p class="label">Car owner</p><b>${esc(r.owner_name)}</b></div><div><p class="label">Pickup</p><b>${esc(r.pickup_address)}</b></div><div><p class="label">Owner confirmed cash</p><b>${esc(requestTime(r.owner_confirmed_at))}</b></div></div><p class="amount">Rental fee: ${money(r.rental_amount)}</p><p class="note">This records both parties' cash handover confirmation in GoRent. It is not a bank or payment gateway confirmation. Deposit is not included.</p><button onclick="window.print()">Print / Save PDF</button></body></html>`}
async function openCashReceipt(id){const tab=window.open('','_blank');if(!tab)throw Error('Allow popups to open the receipt.');try{const data=await api(`bookings/${id}/receipt`);tab.document.open();tab.document.write(cashReceiptHtml(data));tab.document.close();tab.opener=null}catch(error){tab.close();throw error}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-extra]');if(!b)return;e.preventDefault();const id=b.dataset.id,container=$(`#booking-extra-${id}`);try{
  if(b.dataset.extra==='receipt'){await openCashReceipt(id);return}
  if(b.dataset.extra==='messages'){const messages=await api(`bookings/${id}/messages`);container.innerHTML=`<div class="box"><h3>Booking messages</h3>${messages.map(m=>`<p><b>${esc(m.sender_name||'User')}:</b> ${esc(m.body)}</p>`).join('')||'<p class="mut sm">No messages yet.</p>'}<form class="message-form" data-id="${id}"><textarea name="body" maxlength="1000" required placeholder="Write a message to the other party"></textarea><button class="btn s">Send</button></form></div>`}
  if(b.dataset.extra==='review')container.innerHTML=`<form class="box review-form" data-id="${id}"><h3>Review this rental</h3><label>Rating<select name="rating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} star${n===1?'':'s'}</option>`).join('')}</select></label><textarea name="comment" maxlength="1000" placeholder="How was the car and handover?"></textarea><button class="btn s">Submit review</button></form>`;
}catch(x){toast(x.message,true)}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('.message-form,.review-form,.pickup-form,.renter-id-form,.cancel-form'))return;e.preventDefault();const button=form.querySelector('button');button.disabled=true;try{
  if(form.classList.contains('cancel-form')){await api(`bookings/${form.dataset.id}/transition`,{method:'POST',body:{status:'cancelled',reason:form.elements.reason.value.trim()}});await refresh();toast('Booking cancelled. The owner can relist the car.')}
  if(form.classList.contains('renter-id-form')){const data=new FormData(form);if(!data.get('masked_aadhaar'))data.delete('masked_aadhaar');await api(`bookings/${form.dataset.id}/identity`,{method:'POST',body:data});await refresh();toast('ID shared privately with the owner')}
  if(form.classList.contains('pickup-form')){const body={status:'confirmed',pickup_address:form.elements.pickup_address.value.trim()};if(form.elements.pickup_lat.value){body.pickup_lat=form.elements.pickup_lat.value;body.pickup_lng=form.elements.pickup_lng.value}await api(`bookings/${form.dataset.id}/transition`,{method:'POST',body});await refresh();toast('Request accepted. Pickup route shared with renter')}
  if(form.classList.contains('message-form')){await api(`bookings/${form.dataset.id}/messages`,{method:'POST',body:{body:form.elements.namedItem('body').value}});const b=$(`[data-extra="messages"][data-id="${form.dataset.id}"]`);b.click();toast('Message sent')}
  if(form.classList.contains('review-form')){await api('reviews',{method:'POST',body:{booking:Number(form.dataset.id),rating:Number(form.elements.namedItem('rating').value),comment:form.elements.namedItem('comment').value}});form.replaceWith(document.createTextNode('Review submitted.'));toast('Review submitted')}
}catch(x){toast(x.message,true);button.disabled=false}});


